const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
const tokens = data.split(/\s+/).filter(s => s.length > 0);
let ptr = 0;
const N = parseInt(tokens[ptr++]);
const p = new Int32Array(N + 1);
for (let i = 2; i <= N; i++) {
    p[i] = parseInt(tokens[ptr++]);
}

// Build children lists
const children = Array.from({ length: N + 1 }, () => []);
for (let i = 2; i <= N; i++) {
    children[p[i]].push(i);
}

// Binary lifting table
const LOG = 18;
const up = new Array(LOG);
for (let j = 0; j < LOG; j++) up[j] = new Int32Array(N + 1);
up[0][1] = 0;
for (let i = 2; i <= N; i++) up[0][i] = p[i];
for (let j = 1; j < LOG; j++) {
    for (let i = 1; i <= N; i++) {
        const mid = up[j - 1][i];
        up[j][i] = mid === 0 ? 0 : up[j - 1][mid];
    }
}

// Euler tour
const tin = new Int32Array(N + 1);
const tout = new Int32Array(N + 1);
const nodeAtTin = new Int32Array(N + 1);
let timer = 0;
const stack = [[1, 0]];
while (stack.length > 0) {
    const [u, state] = stack.pop();
    if (state === 0) {
        timer++;
        tin[u] = timer;
        nodeAtTin[timer] = u;
        stack.push([u, 1]);
        const ch = children[u];
        for (let i = ch.length - 1; i >= 0; i--) {
            stack.push([ch[i], 0]);
        }
    } else {
        tout[u] = timer;
    }
}

// Fenwick tree
const bit = new Int32Array(N + 2);
function bitAdd(i, delta) {
    while (i <= N) {
        bit[i] += delta;
        i += i & -i;
    }
}
function bitSum(i) {
    let s = 0;
    while (i > 0) {
        s += bit[i];
        i -= i & -i;
    }
    return s;
}
function bitFindKth(k) {
    let idx = 0;
    let bitMask = 1 << (Math.floor(Math.log2(N)));
    while (bitMask !== 0) {
        const t = idx + bitMask;
        if (t <= N && bit[t] < k) {
            idx = t;
            k -= bit[t];
        }
        bitMask >>= 1;
    }
    return idx + 1;
}

function cover(v) {
    const pos = tin[v];
    const cnt = bitSum(pos);
    if (cnt === 0) return 0;
    const idx = bitFindKth(cnt);
    const u = nodeAtTin[idx];
    if (tout[u] >= pos) return u;
    return 0;
}

function kthAncestor(v, k) {
    for (let j = 0; j < LOG; j++) {
        if (k & (1 << j)) {
            v = up[j][v];
        }
    }
    return v;
}

const Q = parseInt(tokens[ptr++]);
const output = [];
for (let q = 0; q < Q; q++) {
    const type = parseInt(tokens[ptr++]);
    if (type === 1) {
        const v = parseInt(tokens[ptr++]);
        const k = parseInt(tokens[ptr++]);
        const r = cover(v);
        let ans;
        if (r !== 0 && r !== v) {
            if (k === 1) ans = r;
            else ans = kthAncestor(r, k - 1);
        } else {
            ans = kthAncestor(v, k);
        }
        output.push(ans);
    } else {
        const v = parseInt(tokens[ptr++]);
        const r = cover(v);
        if (r !== 0) continue;
        let cntBefore = bitSum(tin[v] - 1);
        while (true) {
            const total = bitSum(N);
            if (cntBefore >= total) break;
            const idx = bitFindKth(cntBefore + 1);
            if (idx > tout[v]) break;
            bitAdd(idx, -1);
        }
        bitAdd(tin[v], 1);
    }
}
console.log(output.join('\n'));
